import {beforeEach,describe,it,expect} from "vitest";
import {NomadCatalog} from "../nomad_catalog";
import {DEFAULT_PROFILE,DEFAULT_RULES,DEFAULT_SERVER,type CatalogActor,type PublishedRelease} from "../../../../../shared/nomad-catalog";
const owner:CatalogActor={id:"owner",name:"Owner",admin:false},member:CatalogActor={id:"member",name:"Member",admin:false},admin:CatalogActor={id:"admin",name:"Admin",admin:true};
let data:any,catalog:NomadCatalog,id:string,saveId:string;const metrics={cpuCores:4,totalMemoryMb:16000,availableMemoryMb:12000};let willingness:any={owner:"medium",member:"medium",admin:"medium"};const lookup=(id:string)=>{const actor=[owner,member,admin].find(a=>a.id===id);return actor?{actor,willingness:willingness[id]}:null;};
beforeEach(async()=>{data=null;willingness={owner:"medium",member:"medium",admin:"medium"};catalog=new NomadCatalog(()=>({load:async()=>data?structuredClone(data):null,store:async(_category,_id,value)=>{data=structuredClone(value);},list:async()=>[],delete:async()=>{}}));await catalog.creators(admin,[owner.id],()=>true);const release:PublishedRelease={id:"release",format:"modrinth",source:"upload",fileName:"pack.mrpack",sha256:"a".repeat(64),size:1,profile:{...DEFAULT_PROFILE,mcVersion:"1.20.1"},server:{...DEFAULT_SERVER,memoryMb:1024,eulaAccepted:true},serverArtifact:{url:"https://piston-data.mojang.com/server.jar",sha1:"b".repeat(40),fileName:"server.jar",kind:"jar",installArgs:[],launchArgs:["-jar","server.jar","nogui"]},publishedAt:1,publishedBy:owner.id,fileCount:0};id=(await catalog.create(owner,{name:"Room",description:"",profile:release.profile},release)).id;saveId=(await catalog.save(owner,id,null,{name:"World",description:"",rules:DEFAULT_RULES})).id;await catalog.room(owner,id,saveId,{name:"Room"},true);});
const node=(actor=admin,kind="server",priority=0)=>catalog.createComputeNode(actor,{name:kind,kind,priority,memoryBudgetMb:4096,reserveMemoryMb:512,maxTasks:1,allowAllInstances:true,allowedInstanceIds:[]});
const open=()=>catalog.room(owner,id,saveId,{name:"Room",desiredState:"open"},false);
const poll=(id:string,m=metrics)=>catalog.dispatchComputeNode(id,{metrics:m,lastError:""},lookup);
describe("paired compute placement",()=>{
 it("keeps server registration admin-only and does not leak node credentials",async()=>{await expect(node(owner)).rejects.toMatchObject({code:"forbidden"});const server=await node(),player=await node(owner,"player");expect((await catalog.listComputeNodes(member))).toHaveLength(0);expect(JSON.stringify(await catalog.listComputeNodes(owner,id))).not.toContain("tokenHash");expect(JSON.stringify(await catalog.listComputeNodes(admin))).not.toContain(server.credential.token);await expect(catalog.computeNode(server.node.id,"f".repeat(64))).rejects.toMatchObject({code:"node_authentication_required"});expect((await catalog.computeNode(server.node.id,server.credential.token)).id).toBe(server.node.id);await expect(catalog.updateComputeNode(member,player.node.id,{enabled:false})).rejects.toMatchObject({code:"forbidden"});await expect(catalog.updateComputeNode(owner,player.node.id,{priority:10})).rejects.toMatchObject({code:"forbidden"});});
 it("fixed placement is a hard constraint and rejects a manual ticket",async()=>{const server=await node(),other=await node(admin,"server",100);await catalog.runtimeSettings(owner,id,saveId,{placement:{mode:"fixed",nodeId:server.node.id}});await open();expect((await poll(other.node.id)).assignment).toBeNull();await expect(catalog.issueExecutor(owner,id,saveId,"PC")).rejects.toMatchObject({code:"automatic_placement_enabled"});const assignment=(await poll(server.node.id)).assignment!;expect(assignment).toBeTruthy();const grant=await catalog.executor(assignment.grantId,assignment.token);expect((await catalog.claimExecutor(grant,admin)).lease.nodeName).toBe("server");expect((await poll(server.node.id)).assignment).toBeNull();await catalog.updateComputeNode(admin,server.node.id,{enabled:false});expect((await catalog.executorHeartbeat(grant,admin,1,{phase:"ready"})).stop).toBe(true);});
 it("automatic placement excludes none and insufficient available resources",async()=>{const player=await node(owner,"player"),server=await node(admin,"server",-10);await catalog.runtimeSettings(owner,id,saveId,{placement:{mode:"auto",nodeId:null}});await poll(player.node.id);await poll(server.node.id);willingness.owner="none";await open();expect((await poll(player.node.id)).assignment).toBeNull();expect((await poll(server.node.id,{...metrics,availableMemoryMb:1000})).assignment).toBeNull();expect((await poll(server.node.id)).assignment).toBeTruthy();});
 it("fallback chooses an eligible player before a high-priority server",async()=>{const player=await node(owner,"player"),server=await node(admin,"server",100);await catalog.runtimeSettings(owner,id,saveId,{placement:{mode:"fallback",nodeId:server.node.id}});await poll(player.node.id);await poll(server.node.id);await open();expect((await poll(server.node.id)).assignment).toBeNull();expect((await poll(player.node.id)).assignment).toBeTruthy();});
 it("cannot exceed task reservations or change a running network",async()=>{const server=await node();await catalog.runtimeSettings(admin,id,saveId,{placement:{mode:"fixed",nodeId:server.node.id},ingress:{kind:"generic-tcp",bindHost:"127.0.0.1",bindPort:25565,publicHost:"edge.example.com",publicPort:30065,family:"auto"}});await open();const results=await Promise.all([poll(server.node.id),poll(server.node.id)]);expect(results.filter(r=>r.assignment)).toHaveLength(1);await expect(catalog.runtimeSettings(admin,id,saveId,{placement:{mode:"manual",nodeId:null}})).rejects.toMatchObject({code:"close_rooms_first"});const view=(await catalog.list(owner)).instances[0].saves[0];expect(view.ingress?.publicPort).toBe(30065);expect(view.ingress?.bindPort).toBe(25565);});
 it("keeps network and reserved ports administrator-only",async()=>{const profile={kind:"direct",bindHost:"::1",bindPort:25565,publicHost:"::1",publicPort:25565,family:"ipv6"};await expect(catalog.runtimeSettings(owner,id,saveId,{ingress:profile})).rejects.toMatchObject({code:"forbidden"});await catalog.runtimeSettings(admin,id,saveId,{ingress:profile});const another=(await catalog.save(owner,id,null,{name:"Other",description:"",rules:DEFAULT_RULES})).id;await expect(catalog.runtimeSettings(admin,id,another,{ingress:profile})).rejects.toMatchObject({code:"network_port_reserved"});});
});
